/// <summary>
/// Service class for transfer picking list generation service task
/// </summary>
class METTransferPickingListGenerationTaskService extends SysOperationServiceBase
{

}

Method.Source:
    /// <summary>
    /// If the transfer order is a CSD or a Cross dock order, then it should be auto received
    /// </summary>
    /// <param name = "_transferId">Transfer order number to check if this can be auto-received</param>
    /// <returns>Yes if the order should be auto received, otherwise false</returns>
    private NoYes shouldAutoReceive(InventTransferId _transferId)
    {
        METInventTransferTableExt transExt;
        InventTransferTable trans;
        NoYes ret = NoYes::No;

        select TransferType from transExt
            exists join trans
            where trans.RecId == transExt.InventTransferTable
            && trans.TransferId == _transferId;
        
        if(transExt.TransferType == METCrossDockTransferType::CrossDock || transExt.TransferType == METCrossDockTransferType::CSD)
        {
            ret = NoYes::Yes;
        }

        return ret;
    }

    /// <summary>
    /// processing logic
    /// </summary>
    /// <param name = "_dataContract">The data contract</param>
    public void process(METTransferPickingListGenerationTaskContract _dataContract)
    {
        InventTransferParmTable         inventTransferParmTable;
        InventTransferParmLine          inventTransferParmLine;
        InventTransferUpd               inventTransferUpd;
        WMSPickingRoute                 wmsPickingRoute;
        //CB238 - xDock 
        InventTransferTable inventTransferTable = InventTransferTable::find(_dataContract.parmTransferId());
        try
        {

            inventTransferParmTable.TransferId          = _dataContract.parmTransferId();
            inventTransferParmTable.UpdateType          = InventTransferUpdateType::PickingList;
            // CB715_TransferOrderExtract
            // generate picklist for the order lines where reservation has occurred
            //inventTransferParmTable.PickUpdateQty       = InventTransferPickUpdateQty::AvailableQty;
            inventTransferParmTable.PickUpdateQty       = InventTransferPickUpdateQty::ReservedQty;
            inventTransferParmTable.Reservation         = NoYes::Yes;
            inventTransferParmTable.EditLines           = NoYes::Yes;
            inventTransferParmTable.TransDate           = DateTimeUtil::getSystemDate(DateTimeUtil::getUserPreferredTimeZone());
            
            // CB238 - xDock process - Mark auto-reserve for cross dock and CSD transfer orders
            inventTransferParmTable.AutoReceiveQty = this.shouldAutoReceive(_dataContract.parmTransferId());

            // CB715_TransferOrderExtract
            // This will populate inventTransferParmLine with only TO lines where extraction status=”Ready for extract” only.
            //inventTransferUpd = InventTransferUpdPick::NewParmBuffer(inventTransferParmTable);
            inventTransferUpd = InventTransferUpdPick::METNewParmBuffer(inventTransferParmTable);

            while select forupdate inventTransferParmLine
                where inventTransferParmLine.ParmId     == inventTransferParmTable.ParmId
                    && inventTransferParmLine.TransferId == inventTransferParmTable.TransferId
            {
                if (conFind(_dataContract.parmOSCCodeList(), InventTable::metGetOSCCode(inventTransferParmLine.ItemId, inventTransferParmLine.inventTransferLine().inventDim())) == 0)
                {
                    inventTransferParmLine.delete();
                }
            }

            inventTransferUpd.run();
            
            select firstonly wmsPickingRoute
                where wmsPickingRoute.parmid == inventTransferParmTable.ParmId;

            if (wmsPickingRoute)
            {
                METOrderShipmentLoadCreation        metOrderShipmentloadCreation = METOrderShipmentLoadCreation::construct(METOrderTransactionType::TransferOrder,
                                                                                                                            inventTransferParmTable.TransferId);

                metOrderShipmentloadCreation.createShippmentLoad(true, false);

                if (BusinessEventsConfigurationReader::isBusinessEventEnabled(classStr(METPicklistExtractionBusinessEvent)))
                {
                    METPicklistExtractionBusinessEvent::newFromWMSPickingRoute(wmsPickingRoute).send();
                }
                else
                {
                    throw error("@MET:PickListExtractionBusinessEventNotEnabled");
                }
            }

            this.processSalesRegistrationAndPicking(_dataContract.parmTransferId());
        }
        catch
        {
            error ("@WAX:UpdateCancelled");
        }

        if (!inventTransferUpd.parmInventTransferJour())
        {
            //Update transfer header extraction status
            METInventTransferTableExt::UpdateExtractionStatus(_dataContract.parmTransferId());
        }

    }

